return {
	["Well i have a mission that could interest you. My competitor, walmart is selling mana and health regenerating food dirt cheap. I need few ingredients to undermine her reputation. When you have them, come back to me. You can check exactly what i need in your questlog. Also, when you want to report to me, use our codeword {journeyman} when you have all ingredients."] = "Interes mam do ciebie. Chce zrobic psikusa Biedronce, psikuta mysli ze sobie moze tak bez podatku sprzedawac te zarobaczale jedzenie. Ja jej pokaze na czym polega sabotaz.. to znaczy subtelnosc. Jak zbierzes wszystkie itemy, ktore spisalem w twoim questlogu, to zglos sie do mnie i pamietaj, aby uzyc naszego hasla - {czeladnik}.",
	["Thanks, these are things i needed. Here's your reward."] = "Trzymaj - to za twoja pomoc. Mam nadzieje sie to nie konieci bedziesz chcial mi jeszcze pomoc.",
	["My plan is very sticky. Make sure to not tell anyone, alright?"] = "Taka sytuacja - sliski temat ogolnie. Nie mozesz nikomu powiedziec o tym, ok?",
	["I heard about some elf trying to make a move on madame malkin. I have a plan involving pinata vooodoo.. Bring me the pinata ingredients and i will reward you."] = "Slyszalem o elfie, ktory zarywal do madame malkin. Do mojego planu bede potrzebowac piniaty vodooo.. Przynies mi potrzebne materialy a cie nagrodze.",
	["Now this is a cooperation! Here is your reward."] = "Nooo - i to sie nazywa wspolraca; masz - zasluzyles. Wroc do mnie jeszcze kiedys, a moze bede potrzebowal twojej pomocy.",
	["So you are back. I got a new hustle for you. Bring me items from questlog. Their purpose is to no interest to you, so i wont be bothering you with that."] = "Jednak wrociles. Jest sprawa, ale tym razem nie bedzie latwo. Musze cos odjebac, bo mi sie nudzi, ale nie moga stad sie ruszyc. Potrzebuje kilku przedmiotow, co celow chytrych, acz tajnych. Szczegoly zamiescilem w twoim questlogu.",
	["Yo, whats good? I see you got all things i needed. Take this reward."] = "Mooordo - nie wierzylem, ze ci sie uda. Wielkie dzieki; na pewno nie polazujesz. Lap i nikomu ani slowa.",
	["I have some grim news - for myself at least. Plot owner raised rent prices and i might be out of business soon with that walmart prospering.. I heard he likes exotic items used for black magic. Bring me those and i will reward you."] = 'Nie bede owijal w bawelne - nie jest ciekawie. Wlasciciel tej rudery chce mnie zaplacic, bo "nie place za czynsz", czy cos takiego. Mysle, ze jestem w stanie przekupic go tymi trzema przedmiotami do okultyzmu. Przynies mi przedmioty, ktore wypisalem w twoim questlogu, a cie nagrodze.',
	["I knew i could count on you. Take this as your reward. Thats all for now, i dont want to attract any more attention to my totally legal fluids. See you around!"] = "To to jestes. Wiedzialem, ze moge na ciebie liczyc. Oto twoja nagroda. Nabrales duzo doswiadczenia i pewnie zwiedziles wiele krain w swoich poszukiwanniach. Wiecej nie bede kombinowac, bo jeszcze straznikow na karku bede mial za te akcje. Powodzonka trzym sie!",
	["Potion Conveyor Journeyman"] = "Montownia Potionow",
	["Ask fstab about a new mission."] = "Zapytaj fstaba o nowa misje.",
	["You collected all the items fstab asked and got rewarded for it."] = "Zebrales wszystkie przedmioty, o ktore prosil fstab, za co cie nagrodzil.",
	["BRING_MOULDY_INGREDIENTS_DESCRIPTION"] = function(context)
		local requiredItemsString = ItemsToString(QuestConstants.LocalSupport.PotionConveyorJourneyman.MouldyIngredients)
		local missionDesc = "Fstab poprosil cie o przytarganie nastepujacych przedmiotow:\n" .. requiredItemsString
		return missionDesc
	end,
	["BRING_MOULDY_PINATA_DESCRIPTION"] = function(context)
		local requiredItemsString = ItemsToString(QuestConstants.LocalSupport.PotionConveyorJourneyman.PinataIngredients)
		local missionDesc = "Fstab poprosil cie o przytarganie nastepujacych przedmiotow:\n" .. requiredItemsString
		return missionDesc
	end,
	["BRING_UNKNOWNCAUSE_INGREDIENTS_DESCRIPTION"] = function(context)
		local requiredItemsString = ItemsToString(QuestConstants.LocalSupport.PotionConveyorJourneyman.UnknownCauseIngredients)
		local missionDesc = "Fstab poprosil cie o przytarganie nastepujacych przedmiotow:\n" .. requiredItemsString
		return missionDesc
	end,
	["BRING_COMBAT_INGREDIENTS_DESCRIPTION"] = function(context)
		local requiredItemsString = ItemsToString(QuestConstants.LocalSupport.PotionConveyorJourneyman.CombatIngredients)
		local missionDesc = "Fstab poprosil cie o przytarganie nastepujacych przedmiotow:\n" .. requiredItemsString
		return missionDesc
	end,
	["Come back when you find my shipment."] = "Wroc, gdy zdobedziesz moja przesylke.",
	["Were you able to find my {shipment}?"] = "Czy udalo ci sie znalezc moja {przesylke}?",
	["I hope that you'll find this ticket."] = "Mam nadzieje, ze uda ci sie odnalezc ten bilet.",
	["Thanks a lot! Can't wait to see the match."] = "Dzieki wielkie, nie moge doczekac sie meczu.",
	["This parcel was delayed for a few weeks, and I was beginning to worry that alibaba was trying to trick me. Here's your reward for your help. I found something inside that Stary Anona ordered, probably a {bait} for fish. If you're passing by, deliver it to him. He will surely reward you."] = "Ten parcel spoznial sie juz kilka tygodni i juz sie obawialem, ze alibaba probowal mnie wydymac. Oto twoja nagroda za pomoc. W srodku znalazlem cos, co zamawial Stary Anona, to chyba {zaneta} dla ryb. Jezeli masz po drodze, to mu ja zanies. Na pewno sie odwdzieczy.",
	["Could you take this package to Anon's father? He's surely getting impatient, so he'll reward you for your help."] = "Czy moglbys zaniesc ten pakunek do Starego Anona? Na pewno sie niecierpliwi, wiec nagrodzi cie za twoja pomoc.",
	["Here, please, this box. Anon's father hangs around a pond near the {barracks}."] = "Prosze, oto ta puszka. Stary anona kreci sie przy oczku wodnym obok {koszarow}.",
	["Come back with the food."] = "Wroc jak ogarniesz zarelko.",
	["That's all, thanks for your help."] = "To tyle, dzieki za twoja pomoc.",
	["Thank you for finding perpetrator. Your reward is upstairs, in my drawers.\nMeanwhile I will call to two almighty Mirks, so they will bring my stolen stuff from those undergrounds. [...] I checked the list of stolen items, I saw that he had a ball that Gypsy was looking for. Wait, its not {all}."] = "Dziekuje za wykrycie sprawcy. Twoja nagroda jest na pietrze. Ja tymczasem zadzwonie do dwoch poteznych Mirkow, zeby wyniesli moje skradzione rzeczy z tych podziemi. [...] Sprawdzilem liste skradzionych przedmiotow, i znalazlem tam kule cygana. Byc moze jej szuka. Chwileczke, to nie {wszystko}.",
	["We must stop this thief as fast as possible. He might be scheming how to get back unnoticed and take back his loot. Ask people around, maybe someone saw where he ran to."] = "Tak, musimy jak najszybciej zatrzymac naszego zlodzieja. Juz teraz pewnie planuje jak wrocic do 'biznesu' meblarskiego. Popytaj ludzi wokol, moze ktos widzial, w ktora strone uciekl.",
	["Mister, I'm just fishing here quietly, and all of the sudden I see a man emerging on the surface. You're saying that he is a thief? - he ran that way, to the east."] = "Panie, ja tu sobie spokojnie lowie ryby, az tu nagle jakis czlowiek wyplywa na powierzchnie.\nMowisz ze jest zlodziejem? - pobiegl o tam, na wschod.",
	["I saw someone run past the city gate and then to the east. Maybe he went to the bandit's {camp}?"] = "Widzialem jak ktos pobiegl za brame miasta, a nastepnie na wschod. Moze udal sie w kierunku {obozu} bandytow?",
	["This ain't the opp block, pipe down."] = "Wariacie, nie jestem kapusiem.",
	["Please, you don't think that I am giving any {information} about my - ekhem - contractors just like that."] = "Blagam, nie myslisz chyba ze od tak wydaje jakiekolwiek {informacje} o moich - ekhem - kontrahentach.",
	["Guards! This man got to go, show him where we throw out carcasses."] = "Straze! Ten pan chyba juz musi isc, pokazcie mu gdzie wyrzucamy truchla.",
	["Fine! - calm down, we will get along somehow. What has been stolen from you?"] = "Dobra! - juz spokojnie, jakos sie dogadamy. Co ci skradziono?",
	["Ohh, that dude ... he left on a boat recently. He was asking me for some good place to hide. ...\nI told him to look around at the south of the steppes. That's all I know."] = "Aha, ten typek... niedawno odplynal stad lodka. Pytal mnie, gdzie znajdzie dobre miejsce do ukrycia.\nDoradzalem mu, zeby poszukal na poludniu stepow. To wszystko co wiem.",
	["Commissioner Fisher's barracks are in the southwest part of the city. He sent you here himself, are you drunk?"] = "Koszary Komisarza Ryby znajduja sie w poludniowo-zachodniej czesci miasta. Sam Cie tu przyslal, pijany jestes?",
	["Well done soldier, here's your reward. I found these items among stolen goods which we found in this thug's den."] = "Dobra robota zolnierzu, oto twoja nagroda. Znalazlem te przedmioty wsrod skradzionych rupieci, ktore znalezlismy w norze zbira.",
	["Did you bring my package with you?"] = "Przyniosles ze soba moja paczke?",
	["Thank you for dealing with this matter. Here's your reward. If you're willing, I have another {problem} that you could help me with."] = "Dziekuje Ci za wyjasnienie tej sprawy. Oto twoja nagroda. Jesli to nie klopot, to  mam jeszcze inny {problem}, z ktorym moglbys mi pomoc.",
	["Come back to me once you've resolved the matter with the Old Postman."] = "Wroc do mnie jak wyjasnisz te sprawe z Old Postmanem.",
	["Listen, over the past few years, I've lost a few components of my fishing gear in various ponds and lakes around Mirko. Specifically, I lost my wooden {float}, {reel}, and my old {stool}. Find all these items and {return} to me."] = "Sluchaj, na przestrzeni ostatnich kilku lat zgubilem kilka komponentow mojego sprzetu wedkarskiego w roznych oczkach wodnych i jeziorkach kolo mirko. Dokladnie to zgubilem drewniany {splawik}, {spinning} oraz moj stary {stolek}. Znajdz wszystkie te przedmioty i wroc do mnie.",
	["Come back with all the items i need: {float}, {reel}, and my old {stool}."] = "Ktory z przedmiotow znalazles? Byl to {spinning}, {splawik} orak {stolek}.",
	["Well I do in fact need some help. Wood delivery from Knurow is already delayed by two days.quest I can't check on that myself as im busy doing my business here.."] = "W zasadzie to tak, od jakis 2 dni spoznia sie dostawa drewna z Knurowa, niestety nie moge sie stad ruszyc aby to sprawdzic.",
	["Everything is fine, but some {journeyman} could come in handy. Id say that you look promising."] = "Wszystko w porzadku, ale przydalby mi sie {czeladnik}, wiec jak bedziesz miec ochote to sie zglos.",
	["There's something I need help with. One of the recent packages from the monks has gone missing. It probably got stuck while flowing along the {route} waterway."] = "Jest cos, z czym potrzebuje pomocy. Jedna z ostatnich paczek od mnichow gdzies zaginela. Prawdopodobnie utknela, plynac {szlakiem} wodnym.",
	["I dont need any help, but I would be glad if you bring me one piece of {cloth} of each color. I will definitely pay back for that."] = "Nie potrzebuje pomocy, ale gdybys przyniosl mi po 1 {tkaninie} kazdego koloru to sie na pewno odwdziecze.",
	["I need help, but not in areas that Fisher would suspect me of. But if you want to be useful, please contact me."] = "Potrzebuje pomocy, ale pewnie nie taka o jaka chodzi Rybie, natomiast jakbys chcial sie przydac to sie zglos do mnie.",
	["I dont need any help, thanks. But you can always check my offer."] = "Nie potrzebuje nic, ale sprzedaje passata jakbys byl zainteresowany.",
	["Slurp slurp... I'm feeling better now. To be honest, I can't finish the rest. Either eat or give it to those in need. You can collect your reward from my {son}."] = "Mlask mlask... Juz mi lepiej. W sumie to nie daje rady, reszte mozesz zabrac. Zjedz albo oddaj potrzebujacym. Swoja nagrode mozesz odebrac u Mojego {syna}.",
	["Ball! My fortune telling {ball} has stolen."] = "Kula! Ukradli mi moja {kule} do wrozenia!",
	["He's involved in maritime transport. You can find him in the western part of the suburbs of Mirkotown."] = "Zajmuje sie on transportem morskim. Mozesz go znalezc w zachodniej czesci przedmiesci Mirkotown.",
	["What?! What do you mean the wood is missing? Three days ago I sent a caravan by myself... Something must have happened on its way, could you investigate that?"] = "Jak to drewno nie dotarlo? 3 dni temu wyslalem karawane. Musialo sie cos stac po drodze, zbadaj to jesli mozesz.",
	["What? Are you looking for the wood? Now thats my wood. You can tell Commissioner Fisher that he'll never get it back."] = "Drewno chcesz? To teraz jest drewno Waskiego i jego mafii. Przekaz to komisarzowi Rybie.",
	["Do you want to buy one shimmer swimmer for 1000gp?"] = "Chcesz kupic shimmer swimmer za 1000gp?",
	["Huh, hes a badass? I am the only badass here.\nNow YOU tell ME: am I the only badass in this bitch!?"] = "On jest debesciak? JA JESTEM DEBESCIAK. Powiedz, Waski jest debesciak?",
	["Thats right! And my mafia is badass too?"] = "Bardzo dobre, a jego mafia tez jest debesciak?",
	["Thats right, you are catching up quickly."] = "Dokladnie tak, szybko sie uczysz mlody.",
	["We'll see who's right soon enough!"] = "Zaraz sie przekonamy czy masz racje.",
	["Not this time."] = "Tym razem nie dasz rady.",
	["You thought thats gonna be this easy?!"] = "Sadziles, ze mafie Waskiego tak latwo pokonasz?",
	["Okay, stop! Tell Commissioner Fisher that he can have his wood back."] = "Dobra dobra, nie bij juz. Powiedz komisarzowi Rybie ze moze przyjsc po drewno.  ",
	["Very good, go speak with Trollsky about your reward, from now on you are a certified warrior of MirkoTown."] = "No i bardzo dobrze, zglos sie do Trollskyego po nagrode, od teraz jestes certyfikowanym wojownikiem MirkoTown.",
	["Yeah! You deserve some reward for helping us. You can choose one from the following: {Axe}, {sword}, {club}, {spellbook}, {bolts} and {arrows}."] = "Aaa, za pomoc w odzyskaniu drewna, oczywiscie. Mam pare rzeczy, powiedz tylko czego potrzebujesz, oto ich lista: {Topor}, {miecz}, {obuch}, {ksiazka}, {belty} lub {strzaly}.",
	["Yeah, they're pretty."] = "Tez mi sie podobaja.",
	["Here's your reward. If you'd like to buy more {shimmer swimmer}s just ask me."] = "Prosze, oto twoja nagroda! Jesli bys chcial kolejne {shimmer swimmer}, to moge ci sprzedac.",
	["Return with the stew, or the things might become unpleasant!"] = "Wroc z zupa, bo nie recze!",
	["Visit Lebesgue for this reward, and then meet Fstab. He should provide you some supplies."] = "Po ta nagrode zglos sie do Calki, oraz pozniej do Fstaba po przydzial potionow.",
	["Well, thank you on behalf of our City for your help, get some of these potions."] = "Ah tak, dziekuje ci w imieniu Miasta jeszcze raz za pomoc, tutaj twoj przydzial potionow.",
	["It fell into the small pond nearby once. I hope you find it."] = "Wpadl mi kiedys do stawku obok. Mam nadzieje, ze go znajdziesz.",
	["Few years ago it was peaceful here, but now it is difficult to live with barbarians roaming around.\nTry to take care of them. I know it's going to be hard to get everyone out, but even a few less of their kind will be a success.\nFor proof of defeating a few of them, bring me Brutetamers Staff and Fur Boots, this is their basic equipment.\nSo, would you like to help me?"] = "Ciagle panosza sie tu barbarzyncy. Jeszcze pare lat temu byl tutaj spokoj, jednak teraz ciezko sie z nimi zyje.\nSprobuj sie nimi zajac. Wiem, ze trudno bedzie wykurzyc wszystkich, ale nawet kilku mniej bedzie sukcesem.\nNa dowod pokonania kilku z nich przynies mi Brutetamers Staff oraz Fur Boots, to ich podstawowy ekwupunek.\nTo co piszesz sie na to?",
	["Great, I'll give you a special pickaxe as a reward. I'll tell you what to do with it for later."] = "Swietnie, w nagrode dostaniesz ode mnie specjalny kilof. Podpowiem ci pozniej, do czego mozna go wykorzystac.",
	["Thank you! Here's your reward. Wait a moment! Someone scribbled on my chair with a marker! Oh, {darn} it... For my current condition, only a stew with Chinese ping pong onion, meat from an under-milked centennial bull raised by wolves, all topped with wine stolen from the Kutonapleton winery, will help. Alternatively, a simple rotworm {stew} might do the trick."] = "Dzieki! Oto twoja na nagroda. Ale chwila! - ktos pogryzmolil moj stolek mazakiem! Nosz {kuuurla}.. Na moj aktualny stan pomoze tylko bigos z chinska cebula ping pong, miesem z niedojonego stuletniego byka wychowanego przez wilki i wszystko podlane winem ukradzionym z winnicy kutonapletonu. Ewentualnie moze tez byc zwykla {zupa} rotwormowa.",
	["It slipped into the water by the lake at the beach. I hope you find it."] = "Wpadl mi do wody nad jeziorkiem przy plazy. Mam nadzieje, ze go znajdziesz.",
	["I lost it while fishing by the western gate. I hope you can find it."] = "Zgubilem go lowiac za zachodnia brama. Mam nadzieje, ze go znajdziesz.",
	["Fantastic, thanks! Nevermind about the soup. Just the wings will suffice. You can use my boat whenever you want and take this soccer T-shirt. The size doesn't fit me anyway."] = "Zajebiscie, dzieki. Udko sobie wezme, ale na zupe jednak nie mam ochoty. Mozesz poplywac sobie moja lodka jesli chcesz. Wez to przebranko legii, na mnie i tak za maly rozmiar.",
	["Well, I was supposed to go to my favourite team's match, but the nationalists came up and they ripped the from my hands. Help me get it back."] = "No tak, mialem isc na mecz legii, ale przyszli onrowcy i podjebali mi bilet. Pomoz mi go odzyskac.",
	["Thank you, the quality is not cutting edge but in the end I am Madame Malkin. I can replace your mystic turbans, red robes and green tunics for pieces of cloth from now on."] = "Dziekuje ci, moze nie sa najlepszej jakosci, ale w koncu jestem Madame Malkin.",
	["I think you missed some colour, bring me all six"] = "Mysle ze pominales jakis kolor, przynies wszystkie 6 za jednym razem.",
	["My fortune telling ball! Probably it got stolen, maybe youll help me to find a new one? Come back to show me if you find any."] = "Moja kula wrozbiarska! Prawdopodobnie zostala skradziona, moze uda ci sie znalezc nowa aby ja zastapic, zglos sie wtedy do mnie!",
	["Well, the previous one was better, but this one is fine too. Thank you!\nYou can exchange your {red gem}s for a ring of healing from now on."] = "Hmm, poprzednia byla lepsza, ale tez jest super. Dzieki wielkie!\nW podziece pozwole ci wymieniac u mnie {red gem}y na Ring of Healing.",
	["I like to sew something when I am bored but slowly I am lack of colorful fabrics."] = "Moja kula wrozbiarska! Prawdopodobnie zostala skradziona, moze uda ci sie znalezc nowa aby ja zastapic, zglos sie wtedy do mnie!",
	["I love {rotworm stew} and {roasted dragon wings} from Mickey Dicks. If you make this for me, I will certainly pay you back."] = "Uwielbiam {zupe rotwormowa}, oraz {pieczone smocze skrzydelka} z maka. Jak mi ogarniesz, to na pewno sie odwdziecze.",
	["Wow! You have merlin! Will I get this fish from you if we agree that I will make a nice trophy for you from second one you bring me?"] = "Wow! Masz merlina! Czy dostane ta rybe od ciebie, jesli sie umowimy, ze z drugiej takiej wykonam dla ciebie fajna ozdobe?",
	["Yeah! Lets see.. <bonk blonk> Here you go. Hope you are satisfied"] = "Yeah! Zobaczmy.. <krasz masz> No i mamy. Mam nadzieje ze bedziesz zachwycony!",
	["Find two marlins for me and i will craft you a trophy that you can hang on your house walls."] = "Przyjdz tu z dwoma marlinami, a wytworze dla ciebie trofeum, ktore powiesisz na scianie.",
	["Bring me exactly two marlins"] = "Przynies mi dwa marliny.",
	["Thank you for that marlin. It looks great by the fireplace."] = "Dzieki za przyniesienie ryby. Pieknie wyglada przy kominku.",
	["You are probably not a football devotee like me, but I wanted to go to the {match}. However, someone disrupted my plans."] = "Pewnie nie jestes takim fanem jak ja, ale chcialem wybrac sie na {mecz}. Ktos mi jednak pokrzyzowal plany.",
	["The waterway begins at their rock to the west. Then it flows under the bridge, passes by the orc fortress, and enters a larger lake. From that lake, it flows to the Syn Anona. Somewhere along this waterway, my shipment got stuck."] = "Szlak wodny zaczyna sie od ich skalki na zachodzie. Potem plynie pod mostem, przechodzi obok foretecy orkow, i wpada do wiekszego jeziora. Z tego jeziora plynie do Syna Wedkarza. Gdzies na tej drodze wodnej utknela moja przesylka.",
	["New recruit? Great! Another cannon fodd.. I mean potential soldier.\nAt your first mission, visit all of the main sellers in MirkoTown and ask them if they need some help, after that come back to me to report.\nDon't do anything without consulting me. And now go, there's no time to lose."] = "Nowy rekrut? Wspaniale, kolejne mieso armat... Ekhm, znaczy sie material na zolnierza.\nJako pierwsza misja, przejdz po glownych handlarzach w Mirkotown i spytaj czy nie potrzebuja pomocy, a potem przyjdz do mnie z raportem.\nNie rob nic bez konsultacji ze mna. A teraz ruszaj, nie trac czasu.",
	["Gypsy fortune telling ball? He was a clumsy one ever since.\nThree people are complaining about wood deficiency? It has to be checked as soon as possible. Make your way to Knurowo and ask in about the delivery at the city pier.\nFollow the road at the west of the city and you will find it. I'll give you some potions supply, you may need them."] = "Kula cygana? On nigdy nie byl ostrozny.\nTrzy osoby skarza sie na brak drewna? Trzeba to sprawdzic. Jak najszybciej wyrusz do Knurowa i zapytaj sie w porcie o dostawe.\nIdz droga na zachod od miasta, a na pewno trafisz. Dostajesz ode mnie maly zapas potionow, moga sie przydac.",
	["There is one problem with which you could help me. Some furniture started to disappear from my storages.\nI know for sure that it wasnt Narro's mafia, because they are using wood for different purposes, they are not interested in my products.\nDo you want to help me the one responsible for stealing my furniture?"] = "Jest problem, z ktorym moglbys mi pomoc. Z moich magazynow zaczely znikac gotowe meble.\nWiem, ze to nie sprawka mafii Waskiego, bo oni drewno wykorzystuja do innych celow, i nie interesuja ich moje meble.\nCzy podejmiesz sie odnalezienia delikwenta, ktory kradnie moje meble?",
	["What?! Narro, that moron? He is a wanna gangster now? I'll show him who is the real deal here.\nIt might be a difficult mission for you but I believe that you can make it. I'll give you a better shield because yours looks like crap. If you were to reclaim the wood I'll reward you.\nAnd also you can visit Komor, hes in some trouble recently."] = "Co?! Waski, ten przydupas? Bawi sie w gangsterke? Ja mu pokaze kto jest debesciak.\nTo moze byc dla ciebie trudna misja, ale wierze ze sobie poradzisz. Podaruje ci lepsza tarcze, bo twoja wyglada mizernie. Jak odzyskasz drewno to cie wynagrodze.\nPoza tym mozesz zglosic sie do Komora, wspominal ze potrzebuje kogos do pomocy.",
	["I'm stuck on this shithole and running low on food.\nWould you mind fixing some food for me?"] = "Dzieki wielkie, nie moge doczekac sie meczu. Jest jednak cos jeszcze, siedze na tym wypizdowiu, i konczy mi sie zarcie.\nOgarnal bys mi jakies zamowienie, o ktore cie poprosze?",
	["Very well, let them die. I could use the cane, but you can keep the shoes. Take this pickaxe, just like we agreed.\nAbout this pickaxe - you can use it to smash icicles, for example, or some of the crystals on the island. The magic in this pickaxe is very faint and it only allows you to use it once a week."] = "Bardzo dobrze, niech gina. Laska mi sie przyda, ale buty mozesz sobie zatrzymac. Trzymaj nagrode, tak jak sie umowilismy.\nA wlasnie, ten kilof. Mozesz nim na przyklad rozbijac {sople}, lub niektore z krysztalow na wyspie. Czasem udaje sie pozyskac ich czastki.",
	["Wood, wood delivery. It was supposed to arrive two days ago. Probably another riots in Knurow that blocked the road."] = "Drewno, drewno, mialo byc juz 2 dni temu, znowu pewnie jakas afera w Knurowie ze nie da sie przejechac.",
	["Thanks that you agreed to {help}. I hope that its not another mafia."] = "Dziekuje, ze zgodziles sie mi {pomoc}. Mam nadzieje, ze to nie sprawka kolejnej mafii.",
	["Maybe Gypsy knows something about furniture thief, people like him stick together..."] = "Moze Cygan cos wie o zlodzieju mebli, tacy jak on trzymaja sie razem...",
	["First off, I didnt see anything, Second: ... wait, did you say {furniture}?"] = "Po pierwsze: nic nie widzialem, po drugie: .. czekaj, powiedziales {meble}?",
	["I checked the list of stolen items, I saw that he had a ball that Gypsy was looking for. Wait, its not {all}."] = "Przejrzalem liste skradzionych rzeczy, i widze, ze gdzies trzymal kule, ktorej szuka cygan. Czekaj, to nie {wszystko}.",
	["Recent entries on the list suggest that our thief was stealing food and supplies from the orcs of the south.\nGo to Commissioner Fisher and tell him about it. Also ask him if he knows something about that thief."] = "Ostatnie wpisy na liscie sugeruja, ze nasz zlodziej wykradal wikt i oporzadzenie orkom z poludnia.\nProsze, idz do komisarza Ryby, i opowiedz mu o tym. Spytaj go tez, czy wie cos o tym zlodzieju.",
	["I don't know of anyone who would like to {steal} this junk from Komor."] = "Nie znam nikogo kto chcialby {krasc} te rupiecie od Komora.",
	["Maybe the thief is hiding beneath the MirkoTown, I doubt its anyone from outside of town. However, no one has the courage to check it out."] = "Byc moze zlodziej ukrywa sie w podziemiach MirkoTown, raczej nie jest to nikt z zewnatrz. Nikt jednak nie ma odwagi tego sprawdzic.",
	["DOMINO_BOOK_OF_CONTRABAND_TEXT"] = "Strona 7\n\nUtarg: Sprochniala sztuczna bukowa noga, Krysztalowa kula z mahoniowa podstawka, Debowy stolek.",
	--Questlog
	["Local Support"] = "Pomoc Miejscowym",
	["Two Marlins"] = "Dwa marliny",
	["You delivered two marlins to Fisherman son and were rewarded for it."] = "Dostarczyles marliny do syna wedkarza, za co zostales nagrodzony.",
	["Discernment"] = "Rozeznanie",
	["Commissioner fisher wants to see you, the new recruit, so he can show you your way around the city. Find his quarters in the southern west part of this city, the Mirkotown."] = "Komisarz Ryba chce sie z toba widziec, aby pokazac ci miasto. Jego koszary znajduja sie na poludniowym zachodzie miasta, obok oczka wodnego.",
	["VISIT_DEALERS_STATUS"] = function(context)
		local player = context.player
		local localizer = player:Localizer(LOCALIZERS.LocalSupport)

		local visitedDealers = 0
		local unvisitedNames = ""
		for storageKey, npcName in pairs(QuestConstants.LocalSupport.StorageToVisitNpcName) do
			if player:getStorageValueByKey(storageKey) == MISSION_NOT_STARTED then
				unvisitedNames = unvisitedNames .. "\n" .. localizer:Get(npcName)
			else
				visitedDealers = visitedDealers + 1
			end
		end
		local unvisitedSuffix = ""
		if visitedDealers ~= 10 then
			unvisitedSuffix = "\n\nNie odwiedziles jeszcze tych sprzedawcow:" .. unvisitedNames
		end
		return T("Przejdz sie po glownych sprzedawcach w MirkoTown i zobacz czy nie potrzebuja pomocy, po czym zamelduj o tym Komisarzowi. Odwiedzeni sprzedawcy: :visitedDealers:/10.:unvisitedSuffix:", { visitedDealers = visitedDealers, unvisitedSuffix = unvisitedSuffix })
	end,
	["You visited all dealers in mirkotown and got rewarded by the Commissioner."] = "Odwiedziles wszystkich sprzedawcow w Mirkotown, za co zostales nagrodzony.",
	["Wood Delivery"] = "Dostawa Drewna",
	["Go to Knurowo's port and find out what happened to the wood delivery."] = "Idz do knurowskiego portu dowiedziec sie co z dostawa drewna.",
	["Woody is sure that the wood was shipped on a caravan leaving Knurowo. He asked you to investigate this."] = "Rasiak jest pewny, ze drewno zostalo wyslane karawana, poprosil cie o zbadanie sprawy.",
	["Tell Commissioner that Narro and his mafia stole all of the wood delivery."] = "Przekaz Komisarzowi Rybie, ze Waski i jego mafia zabrali drewno.",
	["Commissioner Fisher ordered you to recover the stolen wood, but he also warned you about the Narro's mafia."] = "Komisarz nakazal ci odzyskanie drewna, lecz ostrzegal przed mafia Waskiego.",
	["Narro gave up, and he is going to let Commissioner take the wood back. Report back to Commissioner."] = "Waski sie poddal i pozwoli Komisarzowi zabrac drewno, przekaz mu te dobre wiesci.",
	["Your merits earned you a special reward. Commissioner sent you to Trollsky, where you can receive your reward."] = "Komisarz za dobrze wykonane zadanie wyslal cie do trollskyiego po nagrode.",
	["Ask fstab for the promised potion supply."] = "Popros Fstaba o swoj przydzial potionow.",
	["You completed the mission and picked up all rewards."] = "Ukonczyles te misje oraz odebrales wszystkie nagrody.",
	["Arrange a special bow from elf abode."] = "Zalatw specjalny luk z siedziby elfow.",
	["You have received the item from Legolas. Go give it to Kitz."] = "Otrzymales luk od Legolasa, przekaz go Kitzowi.",
	["Turns out elvish bow sucks. Kitz now wishes to rook the elves. In return for your efforts you received his old bow."] = "Luk okazal sie chujowy, wiec Kitz pragnie zrobic Dominando elfom. W zamian jednak dal ci jego wlasny luk.",
	["Ocellatus Xddd"] = "OskareK Xddd",
	["Tickets"] = "Bilety",
	["Recover the match tickets that have been stolen from Ocellatus."] = "Odzyskaj bilety na mecz, ktore zostaly skradzione Oskarkowi.",
	["You found the Tickets in a bandits tent. Bring to to Ocellatus."] = "Znalazles bilety w namiocie bandytow. Przynies je teraz od Oskarka.",
	["You gave tickets back to Ocellatus. Ask him for new mission."] = "Oddales bilety, i zwrociles je Oskarkowi. Zapytaj go, czy ma dla ciebie jakies dodatkowe zadanie.",
	["Ocellatus asks you to bring him soup and wings. Ask Pewter for help."] = "Zostales poproszony o zarcie, porozmawiaj z Piotrkiem, jesli bedziesz mial problem.",
	["U brang food to Ocellatus. In his gratitude, he gave you outfit and let you sail his boat."] = "Przyniosles zarcie Oskarkowi, za co podarowal ci stroj, i pozwolil plywac swoja lodka.",
	["Demon Oak"] = "Demoniczny Dab",
	["You have made your way into the den of Demon Oak. Try to find someone who will tell you more about it."] = "Dostales sie o demonizcznego debu. Znajdz kogos, kto powie ci o nim cos wiecej.",
	["Oldrak gave you information regarding Demon Oak. He can bless an axe if you bring him one. The blessed axe should help you fight the Oak."] = "Uzyskales od Oldraka informacje na temat demonicznego debu. Jesli przyniesies mu topor, to poblogoslawi go, aby mogl zostac uzyty w walce z debem.",
	["You defeated the Demon Oak! Report to Oldrak."] = "Pokonales demoniczny dab. Wroc teraz do Oldraka.",
	["You reported to Oldrak about your victory. You have been rewarded for your efforts: Oldrak told you a secret about the way to the Elvish treasury."] = "Opowiedziales Oldrakowi o swoim zwyciestwie. Oldrak opowiedzial ci jak dostac sie do elfickiego skarbca.",
	["Freaking Rats"] = "Przeklete Szczury",
	["Walmart wishes she knew how to repel rats. Find out where Gertrude lives. She should know how to craft a rat poison."] = "Biedronka pragnie przepedzic szczury. Odnajdz Gertrude, ktora potrafi przyzadzac skuteczna trutke.",
	["Gertrude asked you to bring her one mouldy cheese."] = "Gertruda poprosila cie o dostarczenie splesnialego sera, na ktory zaaplikuje trucizne.",
	["The cheese has been poisoned. Bring it to Walmart, so she can repel the rats."] = "Ser jest juz zatruty, zanies go Biedronce, by mogla przepedzic szczury.",
	["Walmart didn't have time to make use of the poisonous cheese, but she already gave you your reward: Carrot cake and a minor gift."] = "Biedronka jeszcze nie przetestowala trutki, jednak w zamian dostales ciato marchewkowe oraz upominek.",
	["Cheap Recycling"] = "Tani Recykling",
	["Malkin asked you to bring her 1 piece of cloth of every color."] = "Malkin poprosila cie o przyniesienie jej po 1 kawalku tkaniny z kazdego koloru.",
	["Madame Malkin is grateful for your effort, and from now on you can exchange mystic turbans, red robe, and green tunic for corresponding pieces of cloth."] = "W podziece mozesz wymieniac u Madame Malkin mystic turbany, red robe oraz green tunic na kolorowe tkaniny.",
	["Broken Orb"] = "Zniszczona Kula",
	["Gypsy needs a new Crystal ball. Bring it to him, and he will reward you abundantly."] = "Cygan pragnie aby przyniesc mu kule wrozbiarska, ktora godnie zastapi poprzednia.",
	["The crystal ball wasn't perfect, but Gypsy is fine with it. Since now he will also let you exchange red gem to ring of healing."] = "Choc kula nie byla idealna, Cygan jest zadowolony i pozwoli ci wymieniac red gem na ring of healing.",
	["Biodegradable"] = "Biodegradowalny",
	["Old postman asked you to find a package. You know that this cargo was supposed to arrive by water from the west."] = "Old postman poprosil Cie o znalezienie paczki. Wiesz, ze ten ladunek mial otrzymac droga wodna ze strony zachodniej.",
	["You found the package for Old Postman. Return to him now."] = "Znalazles paczke Old Postamana. Wroc teraz do niego i mu ja wrecz.",
	["You received a reward from Old Postman in exchange for helping locate the overdue shipment. He mentioned that you can also take a box of fish bait to Anon's father."] = "Otrzymales nagrode od Old Postmana w zamian za pomoc z odnalezieniem zaleglej przesylki. Wspomnial, ze mozesz odniesc Puszke z Zaneta do Starego Anona.",
	["You took the box from Old Postman, which you should deliver to Anon's father."] = "Wziales od Old Postmana puszke, ktora powiniennes odniesc do Starego Anona.",
	["IKEA for the BOLD"] = "IKEA dla zuchwalych",
	["Commissioner Fisher has mentioned that Komor needs help."] = "Komisarz Ryba wspomnial, ze Komor potrzebuje pomocy.",
	["Komor needs help dealing with the disappearing furniture from his warehouse."] = "Komor potrzebuje pomocy w uporaniu sie ze znikajacymi meblami z jego magazynu.",
	["Komor asked you inquire Gypsy if he knows anything about the recent theft of the furniture."] = "Komor polecil ci spytac Cygana, czy wie cos o kradziezy mebli.",
	["Try to find the thief; he's possibly hiding in the sewers."] = "Postaraj sie odnalezc zlodzieja, mozliwe ze ukrywa sie w podziemiach.",
	["You found the thief, but he managed to get away. Try to look around his hideout."] = "Odnalazles zlodzieja, jednak udalo mu sie zwiac. Sprobuj sie rozejrzec po jego kryjowce.",
	["You found a list of stolen items; the thief has apparently stolen more than just furniture. Go to Komor and give him the list."] = "Znalazles dziennik skradzionych przedmiotow, zlodziej widocznie poszerzyl swoje horyzonty poza same umeblowanie. Udaj sie do Komora, i przekaz mu liste.",
	["You helped Komor and got rewarded for that. You have started the new mission 'Needle in a Haystack'."] = "Pomogles Komorowi uporac sie z problemem znikajacych mebli, za co cie wynagrodzil. Rozpoczales nowa misje 'Igla w stogu siana'",
	["You helped Komor find his stolen furniture. Get your reward from the floor above if you haven't already. Visit Komor again to find out what he has found on the list."] = "Pomogles Komorowi w odnalezieniu jego wlasnosci. Udaj sie na pietro jego sklepu, aby otrzymac nagrode, jesli jeszcze tego nie zrobiles. Wroc do Komora by dowiedziec sie, co znalazl na liscie.",
	["Komor asked you to consult Commissioner Fisher about the thief."] = "Komor poprosil cie, abys poradzil sie komisarza Ryby w sprawie zlodzieja.",
	["Fisher asked you to track down the thief. Perhaps someone from nearby saw where he ran away?"] = "Ryba polecil ci wytropic zlodzieja, zanim zaszyje sie gdzies na dobre. Byc moze ktos z okolicy widzial, gdzie uciekl?",
	["Find the bandit camp and see if they have anything to do with it."] = "Znajdz oboz bandytow i dowiedz sie czy maczali palce w tej sprawie.",
	["Ask the bandit leader about the furniture thief."] = "Przepytaj dowodce bandytow w sprawie zlodzieja mebli.",
	["Everything indicates that the thief is trying to smuggle items and hide in the steppes. The bandit leader suggested where you should go now."] = "Wszystko wskazuje na to, ze uciekinier probuje przeszmuglowac przedmioty, i ukryc sie na stepach. Dowodca bandytow zasugerowal, gdzie powinienes sie teraz udac.",
	["You have defeated the Lumberjack Domino, look around his hiding place."] = "Pokonales Drwala Domino, rozejrzyj sie po jego kryjowce.",
	["From now on, you can use Domino's boat. Report to Commissioner Fisher."] = "Od teraz mozesz uzywac jego lodki. Zglos sie do Komisarza Ryby po nagrode za pomoc.",
	["You prematurely ended the efforts of Lumberjack Domino. From now on you can sail his boat from the bandit camp to the south of the steppes."] = "Zakonczyles watek poczynan Drwala Domino, od teraz mozesz plywac jego lodzia z obozowiska bandytow na poludnie stepow.",
	["Settled down Fishmonger"] = "Ustatkowany Fanatyk Wedkarstwa",
	["Anon's father is waiting for his order."] = "Stary Anona czeka na swoje zamowienie.",
	["You helped Anon's father recover his long-awaited package. Ask him for new mission now."] = "Pomogles Staremu Anona z odzyskaniem jego dawno zamowionej paczki. Zapytaj, czy nie ma dla Ciebie nowego zadania.",
	["Anon's father needs help finding some old junk he carried with him for fishing. Search all boats, piers, and swamps around Mirko Town for any found items."] = "Stary Anona potrzebuje pomocy ze znalezieniem jakichs starych rupieci, ktore nosil ze soba na lowy. Przeszukaj wszelkie lodki, pomosty i szuwary w akwenach wokol Mirko, i zwroc znalezione przedmioty.",
	["You helped Anon's father collect his lost tools."] = "Pomogles Staremu Anona z zebraniem jego zgubionych narzedzi.",
	["Anon's father received his table in a deplorable state, ask how you can improve his mood."] = "Stary Anona dostal swoj stolik w nagannym stanie, zapytaj jak mozesz zlagodzic jego nastroj.",
	["Anon's father reacted strongly to the fact that someone destroyed his little table. Bring some of his favorite dishes, and he might calm down. Anon's father mentioned that he loves Rotworm Stew."] = "Stary Anona ostro zareagowal na fakt, iz ktos zniszczyl mu jego stolek. Przynies ktores z jego ulubionych dan, to moze sie nie zesra. Stary Anona wspominal, ze przepada za zupa rotwormowa.",
	["You helped Anon's father with all the troubles. Now, go to his son for your reward."] = "Pomogles Staremu Anona ze wszystkimi klopotami. Udaj sie teraz do jego syna po nagrode.",
	["You have received a reward from the Fisherman Son. You gained the ability to purchase Shimmer Swimmer."] = "Odebrales nagrode od Syna Wedkarza. Zyskales mozliwosc zakupu Shimmer Swimmer.",
	["Unwanted Guests"] = "Zasrani Barbarzyncy",
	["Bring Brutetamers Staff and Fur Boots to Old Man Frost."] = "Przynies dziadkowi Brutetamers Staff oraz Fur Boots, na dowod pokonania barbarzyncow.",
	["You completed Old Man Frost's request."] = "Wypleniles zadania Dziadka Mroza.",
}
